use kimo_core::{commands::{Session,dispatch},render,model::TimeMode};use serde_json::json;
#[test]fn ramp_windows_match_full_source_decode(){let path=std::env::temp_dir().join(format!("kimo-ramp-window-{}.mp4",std::process::id()));assert!(std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","lavfi","-i","testsrc2=size=128x72:rate=30:duration=3","-c:v","libx264",path.to_str().unwrap()]).status().unwrap().success());for managed in [false,true]{for fast in [false,true]{let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":64,"height":36,"fps":25})).unwrap();let a=dispatch(&mut s,"import_media",&json!({"path":path})).unwrap()["asset_id"].clone();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let id=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"media","asset_id":a,"start":0,"in_point":0.13,"duration":1.})).unwrap()["clip_id"].as_str().unwrap().to_string();dispatch(&mut s,"set_speed_ramp",&json!({"clip_id":id,"keys":if fast{json!([[0,2.],[1,1.5]])}else{json!([[0,0.4],[0.5,1.2],[1,0.6]])},"ease":"linear"})).unwrap();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":managed,"linear_resample":managed,"input_transfer":8,"working_gamut":3}})).unwrap();for mode in [TimeMode::Normal,TimeMode::Reverse,TimeMode::Freeze{at:0.76}]{s.project.find_clip_mut(&id).unwrap().time_mode=mode.clone();let mut full=render::Cache::new();render::prepare(&s.project,&mut full).unwrap();let mut sequential=render::Cache::new();for t in [0.,0.12,0.36,0.76,0.96]{let expected=render::render_frame(&s.project,t,&full).unwrap();let mut cold=render::Cache::new();render::prepare_at(&s.project,&mut cold,Some(t)).unwrap();assert_eq!(expected.d,render::render_frame(&s.project,t,&cold).unwrap().d);render::prepare_export_range(&s.project,&mut sequential,t,t).unwrap();assert_eq!(expected.d,render::render_frame(&s.project,t,&sequential).unwrap().d);let fr=cold.frames_of(&id).unwrap();if fast&&matches!(mode,TimeMode::Normal)&&t==0.96{assert!(fr.first>0);assert!(fr.first+fr.len()>25);}}}}}std::fs::remove_file(path).unwrap();}
#[test]fn ramp_source_overrun_is_explicit_but_valid_partial_lookahead_passes(){let path=std::env::temp_dir().join(format!("kimo-ramp-overrun-{}.mp4",std::process::id()));assert!(std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","lavfi","-i","testsrc2=size=64x36:rate=25:duration=2","-c:v","libx264",path.to_str().unwrap()]).status().unwrap().success());let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":64,"height":36,"fps":25})).unwrap();let a=dispatch(&mut s,"import_media",&json!({"path":path})).unwrap()["asset_id"].clone();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let id=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"media","asset_id":a,"start":0,"duration":2.})).unwrap()["clip_id"].as_str().unwrap().to_string();dispatch(&mut s,"set_speed_ramp",&json!({"clip_id":id,"keys":[[0,1.6],[2,0.6]],"ease":"linear"})).unwrap();let mut cache=render::Cache::new();render::prepare_at(&s.project,&mut cache,Some(0.)).unwrap();render::prepare_at(&s.project,&mut cache,Some(1.6)).unwrap();assert!(render::render_frame(&s.project,1.6,&cache).is_ok());let error=render::prepare_at(&s.project,&mut cache,Some(1.96)).unwrap_err();assert!(error.contains("speed ramp overrun"));assert!(error.contains(&id));assert!(error.contains("requested source frames"));std::fs::remove_file(path).unwrap();}
